// Structural validation of the Finance Inbox Request Contract this
// workflow receives from the Intent Router (ADR-0008 Decision 1,
// docs/workflows/finance-inbox-contract.md). Re-validated defensively here
// -- this workflow could in principle be called directly, not only via the
// Router -- same posture as 11-handle-get-budget.json / 12-handle-get-dashboard.json's
// own "Validate Handler Input". No Handler-specific requirement beyond the
// shared contract shape: this is a read-only query against org-wide
// dashboard data (no per-user scoping), so no externalUserId is required.
// Unlike the CREATE_EXPENSE Handler, rawText IS the thing this Handler
// exists to interpret -- but interpretation happens entirely inside AI
// Core's finance-question capability (see "Prepare Finance Question
// Input"), never here. This node only validates that rawText is present as
// a non-empty string -- an empty question has nothing for the AI Core call
// to reason about, so it is rejected before any downstream call is made,
// the one Handler-specific rule this workflow adds beyond the shared
// contract shape.
const req = $json || {};
const reasons = [];

function requireNonEmptyString(field) {
  if (typeof req[field] !== 'string' || req[field].trim().length === 0) {
    reasons.push(`Missing/empty required field: ${field}.`);
  }
}

requireNonEmptyString('contractVersion');
requireNonEmptyString('workflowExecutionId');
requireNonEmptyString('workflowName');
requireNonEmptyString('channel');
requireNonEmptyString('rawText');

if (!Array.isArray(req.attachments)) {
  reasons.push('attachments must be an array.');
}

return [{
  json: {
    valid: reasons.length === 0,
    reason: reasons.join(' '),
    contractVersion: req.contractVersion,
    workflowExecutionId: req.workflowExecutionId,
    workflowName: req.workflowName,
    channel: req.channel,
    externalUserId: req.externalUserId ?? null,
    externalMessageId: req.externalMessageId ?? null,
    rawText: typeof req.rawText === 'string' ? req.rawText : '',
    attachments: Array.isArray(req.attachments) ? req.attachments : [],
  },
}];

// Orchestration-layer rejection (malformed/incomplete envelope, or an
// empty question) -- not a Finance business decision, so this never asks a
// clarifying question -- same posture as the sibling GET_BUDGET/GET_DASHBOARD
// Handlers' own "Build Invalid Input Response". intent stays
// GET_FINANCE_QUESTION (not UNRECOGNIZED): the Router already classified
// this correctly before dispatching here.
const v = $json;

return [{
  json: {
    contractVersion: '1',
    workflowExecutionId: v.workflowExecutionId || 'unknown',
    status: 'error',
    intent: 'GET_FINANCE_QUESTION',
    message: "Sorry, I couldn't process that request. Please try again.",
    data: null,
    clarifyingQuestion: null,
  },
}];

// Gate node between the two read calls this Handler makes -- the Finance
// Service dashboard fetch, then (only on success) the AI Core reasoning
// call. Distinguishes a network/response failure from a successful fetch,
// same class of gate 10-handle-create-expense.json's own "Validate Expense
// Extraction" uses between ITS two calls (AI Core extraction, then the
// Finance API write) -- this Handler needed the same two-call shape
// because, unlike GET_BUDGET/GET_DASHBOARD's single-call handlers, there
// is a second call (AI Core) that must never run against missing/invalid
// dashboard data.
const context = $('Validate Handler Input').item.json;
const result = $json;

if (result && result.error) {
  const message = String((result.error && result.error.message) || result.error);
  console.log(`[Validate Dashboard Response] Finance API call failed: ${message}`);
  return [{ json: { ...context, dashboardOutcome: 'failed' } }];
}

if (!result || result.success !== true || !result.data) {
  console.log(`[Validate Dashboard Response] Finance API returned an unexpected shape: ${JSON.stringify(result)}`);
  return [{ json: { ...context, dashboardOutcome: 'failed' } }];
}

return [{ json: { ...context, dashboardOutcome: 'valid', dashboard: result.data } }];

// Finance Service read failure -- never reaches the AI Core call, which
// has nothing to reason over without real dashboard data. Safe generic
// message, never raw HTTP/response internals -- same posture as every
// other Finance Handler's failure path.
const v = $json;

return [{
  json: {
    contractVersion: '1',
    workflowExecutionId: v.workflowExecutionId,
    status: 'error',
    intent: 'GET_FINANCE_QUESTION',
    message: "Sorry, I couldn't load your finance data right now. Please try again in a moment.",
    data: null,
    clarifyingQuestion: null,
  },
}];

// Builds the AI Core `finance-question` capability's invoke() request
// body -- {input, context}, the same envelope AiCapabilityController.invokeService
// expects and every other Finance AI Core call in this repo already uses
// (docs/adrs/ADR-0014-finance-ai-core-migration.md). input.question is
// rawText FORWARDED UNCHANGED -- this node deliberately does no parsing of
// category, comparison, or spending intent out of it; that interpretation
// is entirely AI Core's job. input.dashboard/input.facts are split from the
// single dashboard payload "Validate Dashboard Response" fetched from the
// real Finance Service: financeFacts (percentages, ranking, hasBudget,
// hasCategorySpecificThresholds) is Finance Service's own deterministic,
// Decimal-safe computation -- forwarded as its own top-level `facts` key so
// the model never has to divide/sort/rank raw dashboard numbers itself, per
// the finance-question-brain prompt's "lookup and restate, never calculate"
// contract. Everything else in dashboard is forwarded unmodified as before.
// context.expectJson is deliberately FALSE (not true, unlike the Router's
// classification call or CREATE_EXPENSE's extraction call) -- the answer is
// free-form natural language for a WhatsApp reply, not structured data.
const input = $json;
const { financeFacts, ...dashboard } = input.dashboard || {};

return [{
  json: {
    ...input,
    aiCoreRequestBody: {
      input: {
        question: input.rawText,
        dashboard,
        facts: financeFacts,
      },
      context: {
        expectJson: false,
        workflowName: '13-handle-get-finance-question',
        workflowExecutionId: input.workflowExecutionId,
      },
    },
  },
}];

// Maps AI Core's finance-question capability response onto the Response
// Contract (ADR-0008 Decision 2). context.expectJson was false on the
// outbound call, so the entry point here is result.data.output (plain
// text), never result.data.outputJson -- unlike every other AI-Core-calling
// node in this Finance domain, this node parses no JSON and enforces no
// field schema, because the model's answer IS the message, verbatim (after
// trimming). Grounding in real dashboard data is enforced entirely by the
// finance-question-brain prompt (eyan-ai-platform) -- this node cannot and
// does not re-verify that the model didn't invent a number; that is a
// prompt-engineering guarantee, not a code-level one, same trust boundary
// every other Finance AI call in this repo already accepts for its own
// prompt's instructions.
const context = $('Validate Dashboard Response').item.json;
const result = $json;

function errorResponse(message) {
  return [{
    json: {
      contractVersion: '1',
      workflowExecutionId: context.workflowExecutionId,
      status: 'error',
      intent: 'GET_FINANCE_QUESTION',
      message,
      data: null,
      clarifyingQuestion: null,
    },
  }];
}

if (result && result.error) {
  const message = String((result.error && result.error.message) || result.error);
  console.log(`[Validate Finance Question Answer] AI Core call failed: ${message}`);
  return errorResponse("Sorry, I couldn't work that out right now. Please try again in a moment.");
}

const data = result && result.data;

if (!data || data.outcome !== 'VALID' || typeof data.output !== 'string' || !data.output.trim()) {
  console.log(`[Validate Finance Question Answer] AI Core did not return a usable answer (outcome: ${data && data.outcome}).`);
  return errorResponse("Sorry, I couldn't work that out right now. Please try again in a moment.");
}

return [{
  json: {
    contractVersion: '1',
    workflowExecutionId: context.workflowExecutionId,
    status: 'success',
    intent: 'GET_FINANCE_QUESTION',
    message: data.output.trim(),
    data: { period: context.dashboard && context.dashboard.period, question: context.rawText },
    clarifyingQuestion: null,
  },
}];
